// GENERATED by scripts/feedback-bundle.js from supabase/functions/oto-feedback/: edit those files, not this one.
// @ts-nocheck (the plain-JavaScript parts are checked by test/feedback.test.js)
// Paste this whole file into Supabase → Edge Functions → oto-feedback (see docs/FEEDBACK_SETUP.md).

// Oto feedback service (Supabase Edge Function "oto-feedback"). Receives messages from Oto's Feedback page, saves them
// in the feedback table and emails bug reports to Oto's maker from Oto's Gmail. Setup: docs/FEEDBACK_SETUP.md.
//
// Secrets (Supabase → Edge Functions → Secrets; never in Oto or the repository):
//   GMAIL_USER          Oto's Gmail address (the sender)
//   GMAIL_APP_PASSWORD  a Google "app password" for that Gmail
//   FEEDBACK_TO         where reports go (your personal email)
//   FEEDBACK_SALT       any long random text (spam limits keep only a scrambled form of the sender's IP)
//   FEEDBACK_EMAIL_ALL  optional: "1" to email ideas and other messages too, not only bugs
// SUPABASE_URL and the project's keys (SUPABASE_SECRET_KEYS) are provided by Supabase inside the function itself.
import nodemailer from 'npm:nodemailer@6';
import { createClient } from 'npm:@supabase/supabase-js@2';

// ---- check.mjs ----
// Oto feedback service: checking what arrives, and the email for Oto's maker. No imports, so the same file runs in
// the Supabase Edge Function (Deno) and in Oto's tests (Node). Mirrors main/feedback.js in the app.
const KINDS = ['bug', 'idea', 'other'];
const MIN = 10, MAX = 4000, REPORT_MAX = 60000;
const EMAIL_RE = /^[^\s@<>()",;:\\]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$/;
const text = (v) => String(v).replace(/\r\n?/g, '\n').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '');
const line = (v, max) => String(v).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);

function check(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return { ok: false, error: 'Nothing to send.' };
  if (!KINDS.includes(body.kind)) return { ok: false, error: 'Pick Bug, Idea or Other.' };
  if (typeof body.message !== 'string') return { ok: false, error: 'Write a message.' };
  const message = text(body.message).trim();
  if (message.length < MIN || message.length > MAX) return { ok: false, error: `The message must be ${MIN} to ${MAX} characters.` };
  const contact = typeof body.contact === 'string' ? line(body.contact, 300) : '';
  if (contact && (contact.length > 254 || !EMAIL_RE.test(contact))) return { ok: false, error: 'That email address doesn\'t look right.' };
  const report = typeof body.report === 'string' ? text(body.report).slice(0, REPORT_MAX) : '';
  const version = typeof body.version === 'string' ? line(body.version, 40) : '';
  const os = typeof body.os === 'string' ? line(body.os, 80) : '';
  return { ok: true, value: { kind: body.kind, message, contact, report, version, os } };
}

const LABEL = { bug: 'Bug', idea: 'Idea', other: 'Other' };

// The email Oto's Gmail sends to Oto's maker.
function mailFor(v, id) {
  const first = line(v.message.split('\n')[0], 70);
  return {
    subject: `${v.kind === 'bug' ? '🐞 Oto bug' : v.kind === 'idea' ? '💡 Oto idea' : '✉️ Oto feedback'}: ${first}`,
    text: [
      `Kind: ${LABEL[v.kind]}`,
      `Oto: ${v.version || '?'} · ${v.os || '?'}`,
      `Reply to: ${v.contact || 'no address given'}`,
      `Feedback #${id}`,
      '',
      v.message,
      '',
      v.report ? '(The technical report is attached as report.txt.)' : '(No technical report.)',
      '',
      '— Sent by Oto\'s feedback form. Reply to this email to answer the person, if they gave an address.',
    ].join('\n'),
    replyTo: v.contact || undefined,
    attachments: v.report ? [{ filename: 'report.txt', content: v.report, contentType: 'text/plain; charset=utf-8' }] : [],
  };
}

// ---- handler.mjs ----
// Oto feedback service: one request = one message. The database and Gmail are handed in (index.ts gives the real
// ones; Oto's tests give stand-ins), so this file has no imports beyond check.mjs.

const LIMIT_HOUR = 5, LIMIT_DAY = 20, BODY_MAX = 100000;

const json = (status, body) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

// deps: { db: { count(ipHash, sinceIso), insert(row) -> id, markEmailed(id) }, sendMail(mail) | null, hash(text), emailAll, now() }
function makeHandler(deps) {
  const now = deps.now || (() => Date.now());
  return async function handle(req) {
    if (req.method !== 'POST') return json(405, { ok: false, error: 'Use POST.' });
    const raw = await req.text();
    if (raw.length > BODY_MAX) return json(413, { ok: false, error: 'That\'s too big.' });
    let body;
    try { body = JSON.parse(raw); } catch { return json(400, { ok: false, error: 'That isn\'t valid.' }); }
    const c = check(body);
    if (!c.ok) return json(400, c);
    const ip = (req.headers.get('x-forwarded-for') || req.headers.get('cf-connecting-ip') || '').split(',')[0].trim() || 'unknown';
    const ipHash = await deps.hash(ip);
    const t = now();
    try {
      if (await deps.db.count(ipHash, new Date(t - 3600e3).toISOString()) >= LIMIT_HOUR) return json(429, { ok: false, error: 'Too many messages from here: try again in an hour.' });
      if (await deps.db.count(ipHash, new Date(t - 86400e3).toISOString()) >= LIMIT_DAY) return json(429, { ok: false, error: 'Too many messages from here today: try again tomorrow.' });
    } catch (e) { console.error('count', e); return json(500, { ok: false, error: 'Oto\'s feedback service has a problem right now. Try again later.' }); }
    const v = c.value;
    let id;
    try {
      id = await deps.db.insert({ kind: v.kind, message: v.message, contact: v.contact || null, oto_version: v.version || null, os: v.os || null, report: v.report || null, ip_hash: ipHash });
    } catch (e) { console.error('insert', e); return json(500, { ok: false, error: 'Oto\'s feedback service couldn\'t save that. Try again later.' }); }
    // bug reports are emailed to Oto's maker (everything, if FEEDBACK_EMAIL_ALL is on); the rest stays saved
    let emailed = false;
    if (deps.sendMail && (v.kind === 'bug' || deps.emailAll)) {
      try { await deps.sendMail(mailFor(v, id)); emailed = true; await deps.db.markEmailed(id); } catch (e) { console.error('email', e && e.message); }
    }
    return json(200, { ok: true, id, emailed });
  };
}

// ---- index.ts ----

const env = (k: string) => Deno.env.get(k) || '';
// The project's secret key (Supabase's new keys, given to the function as SUPABASE_SECRET_KEYS; the old
// service_role key is only a fallback, as Supabase is retiring it). It stays inside Supabase.
function secretKey() {
  try { const k = JSON.parse(env('SUPABASE_SECRET_KEYS') || '{}'); if (k && typeof k.default === 'string' && k.default) return k.default; } catch { /* not set */ }
  return env('SUPABASE_SERVICE_ROLE_KEY');
}
const db = createClient(env('SUPABASE_URL'), secretKey(), { auth: { persistSession: false } });

// Gmail over port 465 (Edge Functions can't use port 587 or 25)
const gmail = env('GMAIL_USER') && env('GMAIL_APP_PASSWORD') && env('FEEDBACK_TO')
  ? nodemailer.createTransport({ host: 'smtp.gmail.com', port: 465, secure: true, auth: { user: env('GMAIL_USER'), pass: env('GMAIL_APP_PASSWORD') } })
  : null;
if (!gmail) console.warn('oto-feedback: GMAIL_USER, GMAIL_APP_PASSWORD or FEEDBACK_TO not set: messages are saved but not emailed');

async function hash(text: string) {
  const data = new TextEncoder().encode(`${env('FEEDBACK_SALT') || 'oto-feedback'}|${text}`);
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', data)), (b) => b.toString(16).padStart(2, '0')).join('');
}

const handle = makeHandler({
  hash,
  emailAll: env('FEEDBACK_EMAIL_ALL') === '1',
  sendMail: gmail ? (m: Record<string, unknown>) => gmail.sendMail({ from: `"Oto Feedback" <${env('GMAIL_USER')}>`, to: env('FEEDBACK_TO'), ...m }) : null,
  db: {
    async count(ipHash: string, since: string) {
      const { count, error } = await db.from('feedback').select('id', { count: 'exact', head: true }).eq('ip_hash', ipHash).gte('created_at', since);
      if (error) throw error;
      return count || 0;
    },
    async insert(row: Record<string, unknown>) {
      const { data, error } = await db.from('feedback').insert(row).select('id').single();
      if (error) throw error;
      return data.id;
    },
    async markEmailed(id: number) {
      const { error } = await db.from('feedback').update({ emailed: true }).eq('id', id);
      if (error) throw error;
    },
  },
});

Deno.serve((req) => handle(req));
